const d={ifox:{baipishu:"Белая книга",jingyingxieyi:"Операционное соглашение",zhucezhengshu:"Свидетельство о регистрации",xinwen:"Новости",rosxinbishangxian:"Запуск новой монеты ROS",jihuibudengren:"Возможности не ждут — ограниченная по времени подписка на новую монету",xiangqing:"Подробнее",zixun:"Новости",daibixinxi:"Информация о токене",daibi:"Токен",wangluo:"Сеть",zonggongyingliang:"Общее предложение",renjiaojia:"Цена подписки",shangjiaojia:"Цена листинга",h1:"Подробное распределение токенов и график вестинга будут опубликованы в официальном whitepaper.",h2:"Ранние участники получают приоритетное распределение.",h3:"Полезность токена",h4:"ROS обеспечивает работу экосистемы Rocket Station.",h5:"Доступ к проектам launchpad Rocket Station",h6:"Голосование по управлению в экосистеме",h7:"Награды и стимулы платформы",h8:"Скидки на торговые комиссии на партнерских платформах",t9:"ROS — это основной utility-токен, обеспечивающий работу экосистемы Rocket Station.",t10:"Распределение токенов",t11:"Публичная продажа",t12:"Развитие экосистемы",t13:"Команда и советники",t14:"Маркетинг и партнерства",t15:"Ликвидность и листинг на биржах",t16:"Награды сообщества",t17:"Распределение ICO ограничено и зависит от доступности.",d1:"Запуск будущего инноваций Web3",d2:"Rocket Station — это децентрализованная инфраструктура запуска Web3, разработанная для ускорения инноваций в блокчейне и поддержки следующего поколения децентрализованных проектов.",d3:"Платформа предоставляет инфраструктуру запуска, поддержку экосистемы и механизмы децентрализованного управления для развивающихся блокчейн-инициатив. Через Rocket Station разработчики могут запускать новые протоколы, сообщества — участвовать в ранних этапах инноваций, а инвесторы — поддерживать будущее технологий Web3.",d4:"Rocket Station стремится создать открытую экосистему, в которой инновации блокчейна могут развиваться без централизованных барьеров.",d5:"Нарратив",d6:"Следующее поколение инноваций в блокчейне требует не только технологий — необходима инфраструктура, позволяющая новым идеям запускаться, масштабироваться и достигать глобальных сообществ.",d7:"Rocket Station была создана, чтобы стать такой инфраструктурой запуска.",d8:"Подобно тому как ракеты выводят спутники на орбиту для обеспечения глобальных коммуникационных сетей, Rocket Station стремится выводить следующее поколение децентрализованных проектов в экономику Web3.",d9:"Каждый проект, запущенный через Rocket Station, представляет новую миссию на пути к децентрализованному будущему.",d10:"Почему Rocket Station?",d11:"Экосистема блокчейна продолжает быстро расширяться, однако многие перспективные проекты сталкиваются с серьезными барьерами на ранних этапах развития.",d12:"Rocket Station решает эту проблему, предоставляя децентрализованную инфраструктуру запуска, которая объединяет разработчиков, сообщества и инвесторов в единой экосистеме.",d13:"Ключевые преимущества включают",d14:"Децентрализованная инфраструктура для запуска проектов Web3",d15:"Возможности раннего доступа для участников экосистемы",d16:"Управление сообществом через токен ROS",d17:"Поддержка развивающихся инноваций в блокчейне",d18:"Rocket Station стремится стать входной точкой для следующего поколения децентрализованных инноваций.",d19:"Ключевые особенности",d20:"Rocket Station предоставляет комплексную инфраструктуру запуска, предназначенную для поддержки роста децентрализованных инноваций.",d21:"Децентрализованная инфраструктура запуска",d22:"Rocket Station позволяет блокчейн-проектам запускаться в децентрализованной экосистеме, снижая барьеры входа и поддерживая открытое участие.",d23:"Управление сообществом",d24:"Через токен ROS участники сообщества могут участвовать в принятии решений по управлению, формируя будущее экосистемы Rocket Station.",d25:"Возможности раннего доступа",d26:"Участники экосистемы Rocket Station получают ранний доступ к новым проектам Web3 и инновационным инициативам.",d27:"Стейкинг и экосистемные стимулы",d28:"Держатели ROS могут участвовать в программах стейкинга и механизмах вознаграждений, направленных на поощрение долгосрочного участия.",d29:"Поддержка экосистемы разработчиков",d30:"Rocket Station предоставляет инструменты, ресурсы и инфраструктуру для поддержки разработчиков в экосистеме Web3.",d31:"Обзор проекта",d32:"Rocket Station выступает как хаб запуска децентрализованных инноваций.",d33:"Предоставляя инфраструктуру запуска, инструменты для разработчиков и механизмы децентрализованного управления, Rocket Station позволяет новаторам выводить новые технологии на глобальный рынок.",d34:"Платформа объединяет разработчиков, сообщества и инвесторов в единой экосистеме, предназначенной для ускорения внедрения Web3.",d35:"Информация о токене",d36:"Название токена",d37:"Символ токена",d38:"Сеть",d39:"Общее предложение",d40:"Цена подписки",d41:"Цена листинга",d42:"Назначение токена",d43:"Токен ROS является основным утилитарным токеном экосистемы Rocket Station.",d44:"Участие в управлении через Rocket Station DAO",d45:"Ранний доступ к запуску токенов экосистемы",d46:"Награды за стейкинг для держателей ROS",d47:"Платежный токен в сервисах экосистемы",d48:"Распределение токенов",d49:"Структура продажи токенов",d50:"Этап",d51:"Цена",d52:"Сид-раунд",d53:"Приватный раунд",d54:"Публичный раунд",d55:"График подписки",d56:"Начало подписки",d57:"Окончание подписки",d58:"Распределение",d59:"Ожидаемый листинг",d60:"Экосистема",d61:"Rocket Station стремится создать децентрализованную экосистему, объединяющую разработчиков, сообщества и инвесторов.",d62:"Экосистема Rocket Station будет поддерживать",d63:"Инфраструктуру запуска проектов Web3",d64:"Управление сообществом через токен ROS",d65:"Инструменты разработчиков и ресурсы экосистемы",d66:"Механизмы финансирования для проектов блокчейна на ранних стадиях",d67:"Через эту экосистему Rocket Station стремится стать глобальным центром децентрализованных инноваций.",d68:"Дорожная карта",d69:"Фаза 1 — Основа",d70:"Разработка концепции Rocket Station",d71:"Проектирование архитектуры платформы",d72:"Планирование структуры экосистемы",d73:"Фаза 2 — Запуск",d74:"Событие подписки на токен ROS",d75:"Расширение сообщества",d76:"Стратегические партнерства в экосистеме",d77:"Фаза 3 — Рост экосистемы",d78:"Привлечение разработчиков",d79:"Расширение инфраструктуры запуска",d80:"Инкубация проектов Web3",d81:"Фаза 4 — Глобальное расширение",d82:"Масштабирование экосистемы",d83:"Развитие децентрализованного управления",d84:"Интеграция глобального сообщества Web3",d85:"Правила участия",d86:"Пользователи должны завершить регистрацию и верификацию аккаунта перед участием в событии подписки.",d87:"Подписка будет проводиться в течение официального периода.",d88:"Распределение токенов произойдет после завершения события подписки.",d89:"Цена листинга будет определена рыночными условиями на момент листинга.",d90:"Официальные ссылки",d91:"Веб-сайт",d92:"Whitepaper",d93:"Отказ от ответственности",d94:"Цифровые активы связаны со значительными рисками и волатильностью цен.",d95:"Участие в блокчейн-проектах должно осуществляться ответственно и с проведением самостоятельного исследования.",d96:"Данная информация предоставляется только в справочных целях и не является финансовой рекомендацией."}};export{d as default};
